sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.form = {
    asset: "",
    issue: "",
    priority: "medium",
    description: ""
  };

  c.submitting = false;
  c.message = "";
  c.messageType = "success";
  c.initial = ((c.data.studentName || "S").charAt(0)).toUpperCase();

  c.submitReport = function() {
    if (c.submitting) return;

    if (!c.form.asset || !c.form.issue ||
        !c.form.priority || !c.form.description ||
        !c.form.description.trim()) {
      c.message = "Please complete all required fields.";
      c.messageType = "error";
      return;
    }

    c.submitting = true;
    c.message = "";

    c.server.get({
      action: "submitReport",
      assetId: c.form.asset,
      issue: c.form.issue,
      priority: c.form.priority,
      description: c.form.description.trim()
    }).then(function(response) {
      var result = response.data || {};

      c.message = result.message ||
        (result.success ? "Report submitted." : "Unable to submit report.");
      c.messageType = result.success ? "success" : "error";

      if (result.success) {
        c.form = {
          asset: "",
          issue: "",
          priority: "medium",
          description: ""
        };
      }
    }, function() {
      c.message = "A server error occurred. Please try again.";
      c.messageType = "error";
    }).finally(function() {
      c.submitting = false;
    });
  };
};

sp_widget.css:
.co-report-page {
  min-height: 100vh;
  background: #f5f7fb;
  color: #30234f;
  font-family: Arial, Helvetica, sans-serif;
}
.co-report-layout {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  min-height: 100vh;
}
.co-report-sidebar {
  background: #f8f4ff;
  border-right: 1px solid #e6dcf7;
  padding: 24px 15px;
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.co-report-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: #30234f;
  margin: 0 0 28px;
}
.co-report-brand-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: #8062c7;
  color: white;
  font-weight: 700;
}
.co-report-brand strong,
.co-report-brand small,
.co-report-sidebar-bottom strong,
.co-report-sidebar-bottom small {
  display: block;
}
.co-report-brand small,
.co-report-sidebar-bottom small {
  color: #837995;
  font-size: 11px;
  margin-top: 4px;
}
.co-report-nav-label {
  color: #968aa8;
  font-size: 10px;
  letter-spacing: 1px;
  font-weight: 700;
  margin: 8px 8px;
}
.co-report-nav {
  display: block;
  padding: 11px 10px;
  border-radius: 9px;
  color: #625775;
  text-decoration: none;
  font-size: 13px;
}
.co-report-nav:hover,
.co-report-nav-active {
  background: #ece4fb;
  color: #6747ad;
}
.co-report-sidebar-bottom {
  margin-top: auto;
  padding: 16px 4px 0;
  border-top: 1px solid #e6dcf7;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
}
.co-report-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: #8062c7;
  color: white;
  display: grid;
  place-items: center;
  font-weight: 700;
}
.co-report-main {
  min-width: 0;
  max-width: 1200px;
  width: 100%;
  padding: 38px 42px;
  margin: 0 auto;
}
.co-report-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  margin-bottom: 26px;
}
.co-report-eyebrow {
  color: #8b7da4;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.3px;
}
.co-report-header h1 {
  margin: 10px 0;
  font-size: 29px;
  color: #30234f;
}
.co-report-header p,
.co-report-intro p,
.co-report-help p {
  color: #81788e;
  font-size: 13px;
  line-height: 1.6;
  margin: 0;
}
.co-report-back {
  border: 1px solid #e1d8f0;
  border-radius: 9px;
  padding: 10px 14px;
  color: #6747ad;
  text-decoration: none;
  font-size: 12px;
  white-space: nowrap;
}
.co-report-intro {
  display: flex;
  gap: 15px;
  align-items: center;
  background: white;
  border: 1px solid #e9e3f2;
  border-radius: 13px;
  padding: 20px;
  margin-bottom: 20px;
}
.co-report-intro-icon {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: #f0e9fc;
  color: #7657b8;
  display: grid;
  place-items: center;
  font-size: 22px;
  font-weight: 700;
}
.co-report-intro h2,
.co-report-form h2 {
  margin: 0 0 7px;
  font-size: 17px;
}
.co-report-form {
  background: white;
  border: 1px solid #e9e3f2;
  border-radius: 13px;
  padding: 26px;
}
.co-report-form-heading {
  margin-bottom: 24px;
}
.co-report-form-heading p {
  color: #81788e;
  font-size: 12px;
  margin: 0;
}
.co-report-field {
  margin-bottom: 22px;
}
.co-report-field label {
  display: block;
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 9px;
}
.co-report-field select,
.co-report-field textarea {
  display: block;
  width: 100%;
  box-sizing: border-box;
  background: #fff;
  border: 1px solid #ddd5e9;
  border-radius: 8px;
  padding: 12px;
  color: #30234f;
  font: inherit;
  font-size: 13px;
}
.co-report-field select:focus,
.co-report-field textarea:focus {
  outline: 2px solid #d8c8f7;
  border-color: #8062c7;
}
.co-report-field textarea {
  resize: vertical;
  min-height: 120px;
}
.co-report-field small {
  display: block;
  color: #92889e;
  font-size: 11px;
  margin-top: 7px;
}
.co-report-actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 12px;
  padding-top: 8px;
}
.co-report-cancel {
  color: #776c87;
  font-size: 13px;
  text-decoration: none;
  padding: 12px;
}
.co-report-actions button {
  background: #8062c7;
  color: white;
  border: 0;
  border-radius: 9px;
  padding: 12px 18px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}
.co-report-actions button:disabled {
  opacity: .6;
  cursor: wait;
}
.co-report-message {
  border-radius: 9px;
  padding: 13px 16px;
  margin-bottom: 18px;
  font-size: 13px;
}
.co-report-message.success {
  background: #eaf7ef;
  color: #21663e;
}
.co-report-message.error {
  background: #fff0ee;
  color: #a3322a;
}
.co-report-help {
  margin-top: 20px;
  padding: 20px;
  border: 1px solid #e9e3f2;
  background: #fbfaff;
  border-radius: 12px;
}
.co-report-help strong {
  font-size: 13px;
}
.co-report-help p {
  margin-top: 6px;
}
.co-report-footer {
  color: #958aa2;
  text-align: center;
  font-size: 11px;
  padding: 24px 0 6px;
}
@media (max-width: 850px) {
  .co-report-layout {
    grid-template-columns: 1fr;
  }
  .co-report-sidebar {
    display: none;
  }
  .co-report-main {
    padding: 24px 16px;
  }
  .co-report-header {
    align-items: flex-start;
  }
}
@media (max-width: 520px) {
  .co-report-header h1 {
    font-size: 24px;
  }
  .co-report-back {
    display: none;
  }
  .co-report-form {
    padding: 18px;
  }
}

sp_widget.script:
(function() {
  var userId = gs.getUserID();

  data.studentName = gs.getUserDisplayName() || "Campus member";
  data.assets = [];
  data.success = false;
  data.message = "";

  function loadAssets() {
    var asset = new GlideRecord("u_campus_asset");
    asset.orderBy("u_asset_name");
    asset.query();

    while (asset.next()) {
      data.assets.push({
        id: asset.getUniqueValue(),
        label: asset.getDisplayValue("u_asset_name") ||
               asset.getDisplayValue()
      });
    }
  }

  if (input && input.action === "submitReport") {
    var assetId = (input.assetId || "").toString();
    var issue = (input.issue || "").toString();
    var priority = (input.priority || "").toString();
    var description = (input.description || "").toString().trim();

    var validIssues = {
      "Damaged": true,
      "Missing": true,
      "Malfunctioning": true,
      "Incorrect Asset Information": true,
      "Other": true
    };

    var validPriorities = {
      "low": true,
      "medium": true,
      "high": true,
      "critical": true
    };

    var assetCheck = new GlideRecord("u_campus_asset");
    var assetExists = assetId && assetCheck.get(assetId);

    if (!assetExists || !validIssues[issue] ||
        !validPriorities[priority] ||
        !description || description.length > 2000) {

      data.success = false;
      data.message = "Please check the asset and required fields, then try again.";

    } else {
      var maintenance = new GlideRecord("u_asset_maintenance");
      maintenance.initialize();
      maintenance.setValue("u_asset", assetId);
      maintenance.setValue("u_issue", issue);
      maintenance.setValue("u_priority", priority);
      maintenance.setValue("u_status", "open");
      maintenance.setValue("u_reported_date", new GlideDateTime());
      maintenance.setValue("u_remarks", description);

      var insertedId = maintenance.insert();

      if (insertedId) {
        data.success = true;
        data.message = "Issue reported successfully. The campus team can now review it.";
      } else {
        data.success = false;
        data.message = "The report could not be saved. Please try again.";
        gs.error("CampusOps: Failed to create an asset maintenance record for user " + userId);
      }
    }
  }

  loadAssets();
})();
